def independent_validation(D_cal, k_cal, val_times, val_vals,
                           ic_val, L=1.0, n_points=51):
    """以不同初始條件（實驗 B）計算獨立驗證 RMSE。

    與留出測試不同，此函式使用獨立初始條件，避免同一物理軌跡上的記憶性。
    回傳 (RMSE, 預測陣列)。
    """
    val_times = np.asarray(val_times, dtype=float).ravel()
    val_vals = np.asarray(val_vals, dtype=float).ravel()
    if val_times.size == 0 or val_times.shape != val_vals.shape:
        raise ValueError("驗證時間與觀測值必須等長非空")
    if not np.all(np.isfinite(val_times)) or not np.all(np.isfinite(val_vals)):
        raise ValueError("獨立驗證資料必須有限")
    if np.any(val_times < 0.0):
        raise ValueError("驗證時間必須非負")

    _, t_vals, c_hist = simulate_diffusion(
        D_cal, L=L, n_points=n_points, t_end=float(np.max(val_times)),
        k=k_cal, save_history=True, initial_cond=ic_val,
    )
    idx_mid = n_points // 2
    t_arr = np.asarray(t_vals)
    preds = []
    for t_obs in val_times:
        idx = int(np.argmin(np.abs(t_arr - t_obs)))
        preds.append(c_hist[idx][idx_mid])
    return compute_rmse(val_vals, preds), np.asarray(preds)


